window.ACDT_CHARGE("issy-les-moulineaux",[{"id":"wd-Q291093","cat":"patrimoine","ville":"issy-les-moulineaux","nom":{"fr":"Pont Mirabeau","en":"Pont Mirabeau","es":"Puente Mirabeau","de":"Pont Mirabeau","it":"Pont Mirabeau","nl":"Pont Mirabeau","pl":"Pont Mirabeau","ru":"Мост Мирабо","uk":"Міст Мірабо","ar":"جسر ميرابو","he":"גשר מירבו","tr":"Mirabeau Köprüsü","el":"Γέφυρα Μιραμπώ","nb":"Pont Mirabeau","fi":"Pont Mirabeau","cs":"Pont Mirabeau","sk":"Pont Mirabeau","hu":"Mirabeau-híd","ro":"Podul Mirabeau","eu":"Mirabeau zubia","zh-CN":"米拉波橋","ja":"ミラボー橋","ko":"미라보 다리","fa":"پل میرابو","vi":"Cầu Mirabeau"},"lat":48.84639,"lon":2.27639,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Pont_Mirabeau_from_Ballon_Generali%2C_Paris_7_August_2016.jpg/960px-Pont_Mirabeau_from_Ballon_Generali%2C_Paris_7_August_2016.jpg","page":"https://commons.wikimedia.org/wiki/File:Pont_Mirabeau_from_Ballon_Generali,_Paris_7_August_2016.jpg","auteur":"Guilhem Vellut from Paris, France","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q291093"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Pont_Mirabeau"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/184264542"}],"recupere":"2026-11-14","court":{"fr":"pont situé à Paris","en":"bridge that crosses the Seine in Paris, France","de":"Brücke über die Seine in Paris (1896)","it":"ponte di Parigi sulla Senna","nl":"stalen brug in 15e arrondissement van Parijs, Frankrijk","tr":"Paris'te köprü","el":"γέφυρα στη Γαλλία","cs":"most v Paříži","hu":"Szajna-híd Párizsban (1896)"},"long":{"ru":"Мост Мирабо — автодорожный мост через Сену в Париже. Соединяет XV и XVI муниципальные округа Парижа. С 29 апреля 1975 года имеет статус исторического памятника.","ja":"ミラボー橋 は、フランスのパリ、セーヌ川に架かる橋である。フランス大統領サディ・カルノーの命により建造された。橋の名は、フランス革命初期の中心的指導者オノーレ・ミラボーにちなむ。ギヨーム・アポリネールの「ミラボー橋」（「ミラボー橋の下をセーヌは流れる...」）で有名である。","pl":"Pont Mirabeau – most na Sekwanie położony w Paryżu, zbudowany w latach 1895–1897.","ko":"미라보 다리는 1895년~1897년에 지어진 다리로서 1975년 프랑스의 역사적인 기념물로서 지정되기도 하였다.","zh-CN":"米拉波桥 是位于法国巴黎塞纳河上的一座桥梁。米拉波桥修建于1893年至1896年，是一座铁质的拱桥。","nl":"De Pont Mirabeau is een brug over de Seine in Parijs, die de Rue de la Convention in het 15e en de Rue de Rémusat in het 16e arrondissement met elkaar verbindt. De brug is genoemd naar Honoré Gabriel de Riqueti, graaf van Mirabeau. Sinds 1975 staat de brug op de Franse monumentenlijst.","ar":"جسر ميرابو هو جسر في باريس بني بين أعوام 1893 و 1896 في باريس على نهر السين. وكان أدرج على قائمة التراث في 29 أبريل 1975. وهو يعتبر كأحد المعالم السياحية والمواقع الأثرية في باريس.","zh-TW":"米拉波橋 是位於法國巴黎塞納河上的一座橋梁。米拉波橋修建於1893年至1896年，是一座鐵質的拱橋。","en":"The pont Mirabeau is an arch bridge which spans the Seine in Paris. It was built between 1895 and 1897 and named after Honoré Gabriel Riqueti de Mirabeau. It was listed a historical monument in 1975.","fr":"Le pont Mirabeau est un pont de Paris construit de 1893 à 1896. Il a été classé monument historique le 29 avril 1975.","de":"Der Pont Mirabeau ist eine Pariser Brücke, die zwischen 1893 und 1896 gebaut wurde. Sie ist nach Honoré Gabriel de Riqueti, comte de Mirabeau benannt und seit dem 29. April 1975 als Monument historique eingestuft.","it":"Il pont Mirabeau è un ponte di Parigi sulla Senna che collega la rue de la Convention e la \"rotonda del ponte Mirabeau\", sulla riva sinistra del fiume, nel XV arrondissement, alla place de Barcelone e alla rue de Rémusat, sulla riva destra del fiume, nel XVI arrondissement. Costruito tra il 1893 e il 1896, il 29 aprile 1975 è stato classificato Monumento storico di Francia. Deve il nome allo scrittore, diplomatico, rivoluzionario, agente segreto e uomo politico Honoré Gabriel Riqueti, conte di Mirabeau.","es":"El puente Mirabeau es un puente parisino sobre el río Sena que une el XV Distrito con el XVI. Fue construido entre 1893 y 1896 y declarado monumento histórico en 1975."},"wiki":{"ru":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D1%81%D1%82_%D0%9C%D0%B8%D1%80%D0%B0%D0%B1%D0%BE","ja":"https://ja.wikipedia.org/wiki/%E3%83%9F%E3%83%A9%E3%83%9C%E3%83%BC%E6%A9%8B","pl":"https://pl.wikipedia.org/wiki/Pont_Mirabeau","ko":"https://ko.wikipedia.org/wiki/%EB%AF%B8%EB%9D%BC%EB%B3%B4_%EB%8B%A4%EB%A6%AC","zh-CN":"https://zh.wikipedia.org/wiki/%E7%B1%B3%E6%8B%89%E6%B3%A2%E6%A9%8B","nl":"https://nl.wikipedia.org/wiki/Pont_Mirabeau","ar":"https://ar.wikipedia.org/wiki/%D8%AC%D8%B3%D8%B1_%D9%85%D9%8A%D8%B1%D8%A7%D8%A8%D9%88_(%D8%A8%D8%A7%D8%B1%D9%8A%D8%B3)","zh-TW":"https://zh.wikipedia.org/wiki/%E7%B1%B3%E6%8B%89%E6%B3%A2%E6%A9%8B","en":"https://en.wikipedia.org/wiki/Pont_Mirabeau","fr":"https://fr.wikipedia.org/wiki/Pont_Mirabeau","de":"https://de.wikipedia.org/wiki/Pont_Mirabeau","it":"https://it.wikipedia.org/wiki/Pont_Mirabeau","es":"https://es.wikipedia.org/wiki/Puente_Mirabeau"}},{"id":"wd-Q2051953","cat":"parcs","ville":"issy-les-moulineaux","nom":{"fr":"Parc André-Citroën","en":"Parc André Citroën","es":"Parc André-Citroën","de":"Parc André-Citroën","it":"Parc André-Citroën","nl":"Parc André Citroën","ru":"Парк Андре Ситроена","he":"פארק אנדרה סיטרואן","tr":"André Citroën Parkı","sv":"Parc André-Citroën","fi":"Parc André-Citroën","cs":"Parc André-Citroën","sl":"Parc André Citroën","ca":"Parc André-Citroën","zh-CN":"安德烈·雪鐵龍公園","zh-TW":"安德烈·雪鐵龍公園","ja":"アンドレ＝シトロエン公園","id":"Taman André Citroën","ms":"Parc André Citroën","ur":"پارک آندرے سیتروئن"},"lat":48.840556,"lon":2.275278,"prix":{"type":"inconnu"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Ballon_de_Paris_%40_Parc_Andr%C3%A9_Citro%C3%ABn_%40_Paris_%2833145680103%29.jpg/960px-Ballon_de_Paris_%40_Parc_Andr%C3%A9_Citro%C3%ABn_%40_Paris_%2833145680103%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Ballon_de_Paris_@_Parc_Andr%C3%A9_Citro%C3%ABn_@_Paris_(33145680103).jpg","auteur":"Guilhem Vellut from Paris, France","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2051953"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Parc_Andr%C3%A9-Citro%C3%ABn"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/151567211"},{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/93491e87-020c-31a4-a532-ed01ed24139b"}],"recupere":"2026-11-14","court":{"fr":"espace vert de Paris, France","en":"urban park in Paris, France","es":"parque urbano en París, Francia","de":"Stadtpark in Paris, Frankreich","nl":"park in Parijs","he":"פארק עירוני בפריז","tr":"Paris'te bahçe veya park","sv":"park i Paris","cs":"park v Paříži","sl":"mestni park v Parizu (Francija)","ja":"パリの公園"},"long":{"ru":"Парк Андре Ситроена — общественный парк площадью 14 га, расположенный на левом берегу Сены в XV округе Парижа.","ja":"アンドレ・シトロエン公園（Parc-André-Citroën）はパリ15区 セーヌ川左岸 のアベル地区にある14ヘクタール (35エーカー) の公共庭園。シトロエンの自動車製造工場跡地上に構築された 公園で、創業者アンドレ・シトロエンの名にちなんで名付けられている。 1986年初頭に着工され、1992年に開園。周囲は住宅と高層ビルが並んでいる。 1992年にオープン時、1世紀以上わたってパリで開設された公園の中で最大の公園。","zh-CN":"安德烈·雪铁龙公园 是法国首都巴黎的一个公园，面积14公顷（35英亩），位于塞纳河左岸的15区。公园所在地之前曾是雪铁龙工厂，公园的名称也来自于雪铁龙公司的创始人。公园开业于1993年，是巴黎近一个世纪开业公园中面积最大的。","zh-TW":"安德烈·雪鐵龍公園 是法國首都巴黎的一個公園，面積14公頃（35英畝），位於塞納河左岸的15區。公園所在地之前曾是雪鐵龍工廠，公園的名稱也來自於雪鐵龍公司的創始人。公園開業於1993年，是巴黎近一個世紀開業公園中面積最大的。","nl":"Het Parc André Citroën is een publiek park in Parijs dat in 1992 geopend werd op het terrein van de voormalige fabrieken van het automerk Citroën, gelegen in het Quartier Javel in het 15e arrondissement. Het park kijkt uit over de linkeroever van de Seine, langs de Quai André-Citroën, waar het autoverkeer langs de Seine over een lengte van 440 meter ondergronds gaat. De hoofdingang bevindt zich aan de rue Cauchy.","en":"Parc André-Citroën is a 14 hectares public park located on the left bank of the river Seine in the 15th arrondissement of Paris.","it":"Il Parc André Citroën è un parco pubblico di 35 ettari, situato sulla parte sinistra della Senna nel XV arrondissement di Parigi. Il parco fu costruito sul sito della fabbrica automobilistica Citroën, il suo nome è quello del fondatore della compagnia André Citroën.","es":"El Parc André-Citroën es un parque urbano situado en la orilla izquierda del Sena, en el emplazamiento de la antigua fábrica de Citroën, en el barrio de Javel del distrito XV de París, creado a principios de 1986 e inaugurado en 1992.","fr":"Le parc André-Citroën est un jardin public situé dans le 15e arrondissement de Paris, sur la rive gauche de la Seine. Aménagé sur une partie de l’ancien site industriel des usines Citroën de Javel, il est inauguré en 1992 et constitue l’un des grands parcs contemporains créés à Paris à la fin du XXe siècle.","de":"Der Parc André Citroën ist eine Parkanlage in Paris. Auf einer Fläche von 14 ha wurde der Park 1992 im Herzen des 15. Arrondissements auf dem Gelände der ehemaligen Citroën-Automobilfabrik im Stil der Postmoderne von den Landschaftsgärtnern Gilles Clément und Alain Provost und den Architekten Patrick Berger, Jean-François Jodry und Jean-Paul Viguier angelegt."},"wiki":{"ru":"https://ru.wikipedia.org/wiki/%D0%9F%D0%B0%D1%80%D0%BA_%D0%90%D0%BD%D0%B4%D1%80%D0%B5_%D0%A1%D0%B8%D1%82%D1%80%D0%BE%D0%B5%D0%BD%D0%B0","ja":"https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%B3%E3%83%89%E3%83%AC%E3%83%BB%E3%82%B7%E3%83%88%E3%83%AD%E3%82%A8%E3%83%B3%E5%85%AC%E5%9C%92","zh-CN":"https://zh.wikipedia.org/wiki/%E5%AE%89%E5%BE%B7%E7%83%88%C2%B7%E9%9B%AA%E9%90%B5%E9%BE%8D%E5%85%AC%E5%9C%92","zh-TW":"https://zh.wikipedia.org/wiki/%E5%AE%89%E5%BE%B7%E7%83%88%C2%B7%E9%9B%AA%E9%90%B5%E9%BE%8D%E5%85%AC%E5%9C%92","nl":"https://nl.wikipedia.org/wiki/Parc_Andr%C3%A9_Citro%C3%ABn","en":"https://en.wikipedia.org/wiki/Parc_Andr%C3%A9-Citro%C3%ABn","it":"https://it.wikipedia.org/wiki/Parc_Andr%C3%A9-Citro%C3%ABn","es":"https://es.wikipedia.org/wiki/Parc_Andr%C3%A9-Citro%C3%ABn","fr":"https://fr.wikipedia.org/wiki/Parc_Andr%C3%A9-Citro%C3%ABn","de":"https://de.wikipedia.org/wiki/Parc_Andr%C3%A9-Citro%C3%ABn"},"site":"https://www.paris.fr/lieux/parc-andre-citroen-1791","adresse":"2, rue Cauchy, 75015 Paris","horaires":"May-Aug Mo-Fr 08:00-21:30; May-Aug Sa,Su 09:00-21:30; Sep Mo-Fr 08:00-20:30; Sep Sa,Su 09:00-20:30; Oct Mo-Fr 08:00-19:30; Oct Sa 09:00-19:30; Oct Su 09:15-19:30; Nov-Apr Mo-Fr 08:00-17:45; Nov-Apr Sa,Su 09:00-17:45"},{"id":"wd-Q2073282","cat":"patrimoine","ville":"issy-les-moulineaux","nom":{"fr":"Pont Aval","en":"Pont Aval","es":"Puente aval","de":"Pont Aval","it":"Pont aval","nl":"Pont Aval","pl":"Pont Aval","sv":"Pont Aval","cs":"Pont aval","sk":"Pont aval","ca":"Pont aval","eu":"Aval zubia","zh-CN":"下游桥","zh-TW":"下游橋","ja":"アヴァル橋","vi":"Pont aval","ur":"پون آوال"},"lat":48.835,"lon":2.263889,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Pont-aval_2.jpg/960px-Pont-aval_2.jpg","page":"https://commons.wikimedia.org/wiki/File:Pont-aval_2.jpg","auteur":"Gede","licence":"CC BY 2.5"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2073282"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Pont_Aval"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/433835333"}],"recupere":"2026-11-14","court":{"fr":"pont parisien","en":"bridge in France","es":"puente de París, en Francia","de":"Straßenbrücke über die Seine im Südwesten von Paris","it":"ponte di Parigi sulla Senna","nl":"brug in Frankrijk","uk":"міст у Франції","ar":"جسر في فرنسا","tr":"Fransa'da köprü","sv":"bro i Paris","cs":"most v Paříži","ja":"パリの橋","id":"jembatan di Perancis"},"long":{"ja":"アヴァル橋(仏 : Pont aval)はフランスのパリ、セーヌ川に架かる橋である。1968年に開通した。パリ市内でセーヌ川に架かる橋では最も下流にある。ただしセーヌ川が大きく蛇行しているため、さらに下流に、パリ市域に含まれるブローニュの森と対岸のコミューンとを結ぶ橋が二つ（アーヴル水道橋の歩道部分とシュレーヌ橋）存在する。","pl":"Pont Aval – most na Sekwanie położony w Paryżu. Most łączy 15 z 16 okręgiem paryskim oraz jest połączony z Bulwarem Peryferyjnym Paryża.","nl":"De Pont Aval is een brug over de rivier de Seine in de Franse hoofdstad Parijs, gebouwd in 1968.","zh-CN":"下游桥 是一条位于法国巴黎的混凝土桥梁，横跨塞纳河，于1968年落成。桥梁长313米，宽35米。此桥属于环城大道的一部分，也是巴黎市区最下游的一条桥梁，故此得名。","zh-TW":"下游橋 是一條位於法國巴黎的混凝土橋梁，橫跨塞納河，於1968年落成。橋梁長313公尺，寬35公尺。此橋屬於環城大道的一部分，也是巴黎市區最下游的一條橋梁，故此得名。","en":"The Pont Aval is a bridge that crosses the Seine in Paris, France. It is open exclusively to motor vehicles traveling along the Boulevard Périphérique, a roadway which encircles the city.","es":"El puente aval es un puente parisino sobre el río Sena que une el XV Distrito con el XVI Distrito. Oficialmente carece de nombre, de hecho la denominación \"aval\" se debe al uso y a su situación geográfica, dado que es el último puente parisíno recorriendo el río hacia su desembocadura.","fr":"Le pont Aval est un pont situé à Paris, en France.","de":"Der Pont Aval ist eine Straßenbrücke über die Seine im Südwesten von Paris. Sie führt den Boulevard périphérique über den Fluss und verbindet das 16. Arrondissement mit dem 15. Arrondissement. Neben der Seine überbrückt sie auch den Quai Saint-Exupéry am Nordufer und den Quai d’Issy-les-Moulineaux am Südufer.","it":"Il Pont aval è un ponte di Parigi che attraversa la Senna. È un ponte autostradale percorso dal Boulevard périphérique ed è il ponte parigino più lungo (312,5 metri). Si trova a sud-ovest della città e confina con i Comuni di Issy-les-Moulineaux e Saint-Exupéry. Mette in comunicazione gli arrondissement XV e XVI, agli svincoli rispettivamente di Porte de Sèvres e Porte de Saint-Cloud. È stato inaugurato nel 1968."},"wiki":{"ja":"https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%B4%E3%82%A1%E3%83%AB%E6%A9%8B","pl":"https://pl.wikipedia.org/wiki/Pont_Aval","nl":"https://nl.wikipedia.org/wiki/Pont_Aval","zh-CN":"https://zh.wikipedia.org/wiki/%E4%B8%8B%E6%B8%B8%E6%A1%A5","zh-TW":"https://zh.wikipedia.org/wiki/%E4%B8%8B%E6%B8%B8%E6%A1%A5","en":"https://en.wikipedia.org/wiki/Pont_aval","es":"https://es.wikipedia.org/wiki/Puente_aval","fr":"https://fr.wikipedia.org/wiki/Pont_Aval","de":"https://de.wikipedia.org/wiki/Pont_Aval","it":"https://it.wikipedia.org/wiki/Pont_aval"}},{"id":"wd-Q2273701","cat":"patrimoine","ville":"issy-les-moulineaux","nom":{"fr":"Pont de Grenelle-Cadets-de-Saumur","en":"Pont de Grenelle","es":"Puente de Grenelle","de":"Pont de Grenelle","it":"Pont de Grenelle","pt":"Ponte de Grenelle","nl":"Pont de Grenelle","pl":"Pont de Grenelle","he":"גשר גרנל","tr":"Grenelle Köprüsü","el":"Γέφυρα της Γκρενέλ","da":"Pont de Grenelle","nb":"Pont de Grenelle-Cadets-de-Saumur","cs":"Pont de Grenelle","sk":"Pont de Grenelle","ca":"Pont de Grenelle","eu":"Grenelleko zubia","zh-CN":"格勒纳勒桥","zh-TW":"格勒納勒橋","ja":"グルネル橋","vi":"Cầu Grenelle"},"lat":48.85029,"lon":2.28007,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Pont_de_Grenelle_from_Pont_Mirabeau%2C_Paris_10_April_2014.jpg/960px-Pont_de_Grenelle_from_Pont_Mirabeau%2C_Paris_10_April_2014.jpg","page":"https://commons.wikimedia.org/wiki/File:Pont_de_Grenelle_from_Pont_Mirabeau,_Paris_10_April_2014.jpg","auteur":"DXR","licence":"CC BY-SA 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2273701"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Pont_de_Grenelle"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/183617212"}],"recupere":"2026-11-14","court":{"fr":"pont français","en":"bridge in Paris, France","de":"Straßenbrücke in Paris","it":"ponte di Parigi sulla Senna","pt":"ponte em Grenelle, França","nl":"liggerbrug in Parijs, Frankrijk","he":"גשר בפריז, צרפת","tr":"Paris'te köprü","el":"γέφυρα στο Παρίσι","cs":"most v Paříži"},"long":{"pl":"Pont de Grenelle – stalowy most na rzece Sekwanie położony w Paryżu. Most łączy 15. okręg Paryża z 16. okręgiem. Część mostu przechodzi przez wyspę Île aux Cygnes położoną na Sekwanie. Most został wybudowany w 1966 roku i zastąpił stary most, który został zbudowany w 1873 roku. Most opiera się na konstrukcji łukowej. Most przechodzi tuż za statuą wolności znajdującą się na końcu Île aux Cygnes. Długość mostu wynosi 220 metrów a szerokość 30 m.","ja":"グルネル橋(仏 : Pont de Grenelle)は、フランスのパリ、セーヌ川に架かる橋である。白鳥の島（白鳥の小径）を跨ぎ、15区のリノワ通りと16区のプレジダン＝ケネディ（河岸）通りを結んでいる。","zh-CN":"格勒纳勒桥 是一条位于法国巴黎的钢制梁桥，建于1827年，连接巴黎十五区和巴黎十六区，横跨塞纳河以及河道中央的天鹅岛。桥梁长173米，宽20米，现存建筑于1966年落成。","zh-TW":"格勒納勒橋 是一條位於法國巴黎的鋼製梁橋，建於1827年，連接巴黎十五區和巴黎十六區，橫跨塞納河以及河道中央的天鵝島。橋梁長173米，寬20米，現存建築於1966年落成。","de":"Der Pont de Grenelle ist eine Straßenbrücke in Paris über die Seine und die Île aux Cygnes (Schwaneninsel), die 1825 für den Brückenbau aufgeschüttet wurde und den Fluss hier in zwei Arme teilt.","es":"El puente de Grenelle es un puente parisino sobre el río Sena que une el XV Distrito con el XVI Distrito. Siguiendo el curso del río, es el tercer y último puente en cruzar la Île aux Cygnes.","en":"The Pont de Grenelle-Cadets de Saumur, formerly known as Pont de Grenelle is a bridge that crosses the Seine River in Paris, France. It connects the city's 15th and 16th arrondissements, and passes through the Île aux Cygnes. Constructed of steel, it is a girder bridge. The current bridge was constructed in 1966-68. It replaced an iron bridge that had stood since 1875. which had replaced the original wooden tollbridge built in 1827-29. The bridge passes behind a replica of the Statue of Liberty.","fr":"Le pont de Grenelle-Cadets-de-Saumur est un pont routier de Paris franchissant la Seine et reliant le 15e et le 16e arrondissement. Il est construit entre 1966 et 1968 sur l’emplacement d'un pont bâti en 1874, lui-même construit à la suite de l'effondrement d'un premier pont construit à cet endroit en 1827.","it":"Il pont de Grenelle-Cadets-de-Saumur è un ponte di Parigi costruito tra il 1966 e il 1968 sul luogo di un precedente ponte eretto nel 1827."},"wiki":{"pl":"https://pl.wikipedia.org/wiki/Pont_de_Grenelle","ja":"https://ja.wikipedia.org/wiki/%E3%82%B0%E3%83%AB%E3%83%8D%E3%83%AB%E6%A9%8B","zh-CN":"https://zh.wikipedia.org/wiki/%E6%A0%BC%E5%8B%92%E7%BA%B3%E5%8B%92%E6%A1%A5","zh-TW":"https://zh.wikipedia.org/wiki/%E6%A0%BC%E5%8B%92%E7%BA%B3%E5%8B%92%E6%A1%A5","de":"https://de.wikipedia.org/wiki/Pont_de_Grenelle","es":"https://es.wikipedia.org/wiki/Puente_de_Grenelle","en":"https://en.wikipedia.org/wiki/Pont_de_Grenelle","fr":"https://fr.wikipedia.org/wiki/Pont_de_Grenelle","it":"https://it.wikipedia.org/wiki/Pont_de_Grenelle"}},{"id":"wd-Q2307584","cat":"patrimoine","ville":"issy-les-moulineaux","nom":{"fr":"Pont Rouelle","en":"Pont Rouelle","es":"Puente Rouelle","de":"Pont Rouelle","it":"Pont Rouelle","nl":"Pont Rouelle","pl":"Pont Rouelle","he":"גשר רואל","tr":"Rouelle Köprüsü","da":"Pont Rouelle","cs":"Pont Rouelle","sk":"Pont Rouelle","sl":"Pont Rouelle","eu":"Rouelle zubia","zh-CN":"鲁埃勒桥","zh-TW":"魯埃勒橋","ja":"ルーエレ橋","vi":"Cầu Rouelle"},"lat":48.85227,"lon":2.28306,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Pont_Rouelle_and_Eiffel_Tower%2C_Paris_19_October_2017.jpg/960px-Pont_Rouelle_and_Eiffel_Tower%2C_Paris_19_October_2017.jpg","page":"https://commons.wikimedia.org/wiki/File:Pont_Rouelle_and_Eiffel_Tower,_Paris_19_October_2017.jpg","auteur":"Tom Hilton","licence":"CC BY 2.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2307584"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Pont_Rouelle"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/623828794"}],"recupere":"2026-11-14","court":{"fr":"pont français","en":"bridge in Paris, France","de":"Eisenbahnbrücke in Paris, Frankreich","it":"ponte di Parigi sulla Senna","nl":"spoorbrug in Parijs, Frankrijk","tr":"Paris'te köprü","cs":"most v Paříži","sk":"most vo Francúzsku","sl":"železniški most v Parizu (Francija)","vi":"cầu đường sắt qua sông Seine ở Paris, Pháp"},"long":{"pl":"Pont Rouelle – most a Sekwanie położony w Paryżu. Most łączy 15. okręg Paryża z 16. okręgiem. Część mostu przechodzi przez położoną na Sekwanie wyspę Île aux Cygnes.","ja":"ルエル橋(仏 : Pont Rouelle Rouelle発音例 Rouelle Wiktionnaire)は、フランスのパリ、セーヌ川に架かる鉄道橋である。","zh-CN":"鲁埃勒桥 是一条位于法国巴黎的钢制拱桥，连接巴黎十五区和巴黎十六区，横跨塞纳河以及河道中央的天鹅岛。桥梁长173米，宽20米。于1900年世界博览会兴建，1937年被弃用，现存建筑于1988年落成。目前，此桥只允许大区快铁C线的列车经过。鲁埃勒桥得名于鲁埃勒路，该路以法国化学家、药剂师纪尧姆-弗朗索瓦·鲁埃勒命名。","zh-TW":"魯埃勒橋 是一條位於法國巴黎的鋼制拱橋，連接巴黎十五區和巴黎十六區，橫跨塞納河以及河道中央的天鵝島。橋梁長173米，寬20米。於1900年世界博覽會興建，1937年被棄用，現存建築於1988年落成。目前，此橋只允許大區快鐵C線的列車經過。魯埃勒橋得名於魯埃勒路，該路以法國化學家、藥劑師紀堯姆-弗朗索瓦·魯埃勒命名。","en":"The Pont Rouelle is a railway bridge in Paris that crosses the river Seine. It connects the city's 15th and 16th arrondissements, and passes through the Île aux Cygnes. Constructed of steel, the bridge is 173 metres (567 feet) long and 20 metres (66 feet) wide. It is currently used for railway service, carrying the RER C.","it":"Il pont Rouelle è un ponte ferroviario di Parigi che attraversa la Senna tra i due ponti stradali pont de Grenelle e ponte di Bir-Hakeim unendo il XVI arrondissement al XV. Esso è costituito in realtà da più parti, distinte anche costruttivamente, poiché passa attraverso l'Île aux Cygnes. Su di esso transita la linea C della rete espressa regionale dell'Île-de-France.","es":"El puente de Rouelle es un puente parisino sobre el río sena que une el XV Distrito con el XVI Distrito. Tiene un uso exclusivamente ferroviario, siendo utilizado por la línea C de la red de cercanías suburbanos de la ciudad.","de":"Der Pont Rouelle ist eine Eisenbahnbrücke in Paris. Sie überspannt die Seine zwischen dem 15. Arrondissement und dem 16. Arrondissement und führt über die île aux Cygnes (Schwaneninsel). Diese Brücke bedient den Abschnitt der RER-Linie C, der die Verbindung Vallée de Montmorency – Invalides darstellt.","fr":"Le pont Rouelle, situé à Paris, enjambe la Seine entre le 15e arrondissement et le 16e arrondissement, en passant par l'île aux Cygnes. Ce pont, uniquement ferroviaire, supporte la branche de la ligne C du RER assurant la liaison dite « Vallée de Montmorency - Invalides »."},"wiki":{"pl":"https://pl.wikipedia.org/wiki/Pont_Rouelle","ja":"https://ja.wikipedia.org/wiki/%E3%83%AB%E3%82%A8%E3%83%AB%E6%A9%8B","zh-CN":"https://zh.wikipedia.org/wiki/%E9%B2%81%E5%9F%83%E5%8B%92%E6%A1%A5","zh-TW":"https://zh.wikipedia.org/wiki/%E9%B2%81%E5%9F%83%E5%8B%92%E6%A1%A5","en":"https://en.wikipedia.org/wiki/Pont_Rouelle","it":"https://it.wikipedia.org/wiki/Pont_Rouelle","es":"https://es.wikipedia.org/wiki/Puente_de_Rouelle","de":"https://de.wikipedia.org/wiki/Pont_Rouelle","fr":"https://fr.wikipedia.org/wiki/Pont_Rouelle"}},{"id":"wd-Q2426843","cat":"patrimoine","ville":"issy-les-moulineaux","nom":{"fr":"Pont du Garigliano","en":"Pont du Garigliano","es":"Puente del Garigliano","de":"Pont du Garigliano","it":"Pont du Garigliano","nl":"Pont du Garigliano","pl":"Pont du Garigliano","tr":"Garigliano Köprüsü","nb":"Pont du Garigliano","cs":"Pont du Garigliano","sk":"Pont du Garigliano","eu":"Garigliano zubia","zh-CN":"加里利亚诺桥","zh-TW":"加里利亞諾橋","ja":"ガリリアーノ橋","vi":"Cầu Garigliano"},"lat":48.839361,"lon":2.268333,"prix":{"type":"libre"},"photo":{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Pont_du_Garigliano_Paris_FRA_001.JPG/960px-Pont_du_Garigliano_Paris_FRA_001.JPG","page":"https://commons.wikimedia.org/wiki/File:Pont_du_Garigliano_Paris_FRA_001.JPG","auteur":"ignis","licence":"CC BY-SA 3.0"},"sources":[{"nom":"Wikidata","licence":"CC0","url":"https://www.wikidata.org/wiki/Q2426843"},{"nom":"Wikipédia","licence":"CC BY-SA 4.0","url":"https://fr.wikipedia.org/wiki/Pont_du_Garigliano"},{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/374027143"}],"recupere":"2026-11-14","court":{"fr":"pont enjambant la Seine à Paris","en":"bridge in France","es":"puente de Francia","de":"Brücke im 15. Arrondissement von Paris, Frankreich","it":"ponte di Parigi sulla Senna","nl":"brug in Frankrijk","uk":"міст у Франції","ar":"جسر في باريس، فرنسا","tr":"Paris'te köprü","cs":"most v Paříži","zh-CN":"法国巴黎的桥梁","ja":"パリの橋","id":"jembatan di Perancis"},"long":{"ja":"ガリリアーノ橋(仏 : Pont du Garigliano)は、フランスのパリ、セーヌ川に架かる橋である。15区のマーシャル・ヴァラン大通りと16区のエグゼルマン大通りを結んでいる。すぐそばにフランス・テレビジョン、ジョルジュ・ポンピドゥー病院がある。","pl":"Pont du Garigliano – most na rzece Sekwanie położony w Paryżu.","zh-CN":"加里利亚诺桥 是法国巴黎的一座横跨塞纳河的桥，是欧特伊高架桥的接替者。桥名是为了纪念1944年意大利战役期间的加里利亚诺河之战。","zh-TW":"加里利亞諾橋 是法國巴黎的一座橫跨塞納河的橋，是歐特伊高架橋的接替者。橋名是為了紀念1944年義大利戰役期間的加里利亞諾河之戰。","fr":"Le pont du Garigliano est un pont enjambant la Seine à Paris et succédant au viaduc d'Auteuil.","de":"Der Pont du Garigliano ist eine Straßenbrücke über die Seine im Westen von Paris, die 1966 eröffnet wurde. Sie verbindet das 15. Arrondissement mit dem 16. Arrondissement der Stadt und ersetzte den Pont du Point-du-Jour mit dem aufgesetzten Viaduc d’Auteuil von 1865.","en":"The Pont du Garigliano is a bridge across the Seine in Paris.","es":"El puente del Garigliano es un puente ubicado en la ciudad de París, Francia. Sobre el río Sena que une el XV Distrito con el XVI Distrito. El puente debe su nombre al río Garigliano escenario de la batalla de Montecassino celebrada durante la Segunda Guerra Mundial.","it":"Il Pont du Garigliano è un ponte di Parigi che attraversa la Senna. Prende il nome dalla battaglia di Garigliano, vicino a Montecassino, combattuta dalle truppe francesi nel giugno 1944, avvenuta in Italia nel corso della seconda guerra mondiale."},"wiki":{"ja":"https://ja.wikipedia.org/wiki/%E3%82%AC%E3%83%AA%E3%83%AA%E3%82%A2%E3%83%BC%E3%83%8E%E6%A9%8B","pl":"https://pl.wikipedia.org/wiki/Pont_du_Garigliano","zh-CN":"https://zh.wikipedia.org/wiki/%E5%8A%A0%E9%87%8C%E5%88%A9%E4%BA%9A%E8%AF%BA%E6%A1%A5","zh-TW":"https://zh.wikipedia.org/wiki/%E5%8A%A0%E9%87%8C%E5%88%A9%E4%BA%9A%E8%AF%BA%E6%A1%A5","fr":"https://fr.wikipedia.org/wiki/Pont_du_Garigliano","de":"https://de.wikipedia.org/wiki/Pont_du_Garigliano","en":"https://en.wikipedia.org/wiki/Pont_du_Garigliano","es":"https://es.wikipedia.org/wiki/Puente_del_Garigliano","it":"https://it.wikipedia.org/wiki/Pont_du_Garigliano"}},{"id":"osm-w105152351","cat":"restaurants","ville":"issy-les-moulineaux","nom":"L'Île","lat":48.825857,"lon":2.256324,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/105152351"},{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/af638f20-391c-3cd0-a9aa-4c20dfc8435c"}],"recupere":"2026-11-14","long":{"fr":"Le parc Eve® de 18 hectares vous attend pour une escapade en pleine nature, entre vastes pelouses, bois et jardins thématiques. Découvrez le jardin des lavandes, la mare écologique, le potager bio et les aires de jeux. N'oubliez pas la Tour aux Figures de Jean Dubuffet. Une expérience naturelle et culturelle incontournable!"},"site":"https://www.restaurant-lile.com/","adresse":"170 Quai de Stalingrad, 92130 Issy-les-Moulineaux","tel":"+33 1 41099999","horaires":"Mo-Su 11:00-02:00","cuisine":"bistro;french"},{"id":"osm-w618758811","cat":"restaurants","ville":"issy-les-moulineaux","nom":"River Café","lat":48.829417,"lon":2.260346,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/way/618758811"},{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/913da604-ca71-32b1-afba-c7fe50a53c47"}],"recupere":"2026-11-14","long":{"fr":"Situé à Issy-les-Moulineaux, le River Café est une péniche en pleine nature offrant une cuisine délicate et inventive. Fréquenté par les professionnels des médias en semaine, c'est également un endroit prisé des familles le week-end. Une escapade à la campagne à proximité de Paris, idéale pour se ressourcer et savourer des mets raffinés dans un cadre unique."},"site":"https://rivercafe.fr/","adresse":"146 Quai de la Bataille de Stalingrad, 92130 Issy-les-Moulineaux","tel":"+33140935020","horaires":"Mo-Su 12:00-24:00","cuisine":"french"},{"id":"osm-n2302887736","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Belle Isle","lat":48.828955,"lon":2.266283,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/2302887736"}],"recupere":"2026-11-14","site":"https://belle-isle-92.fr/","adresse":"10 Square Louis Blériot, 92130","tel":"+33 1 46 38 66 28","horaires":"Mo-Th 07:00-16:00; Fr 07:00-23:00","cuisine":"crepe;french"},{"id":"osm-n4962418024","cat":"marches","ville":"issy-les-moulineaux","nom":"Marché des Epinettes","lat":48.817417,"lon":2.260818,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/4962418024"}],"recupere":"2026-11-14","site":"https://www.issy.com/ma-ville/vie-economique/commerce-de-proximite/les-marches-dissy","tel":"+33 1 41 23 80 00","horaires":"Th 07:00-13:00; Sa 07:00-13:00"},{"id":"osm-n4962498454","cat":"shopping","ville":"issy-les-moulineaux","nom":"La Fromagerie Quatrehomme","lat":48.826565,"lon":2.27879,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"OpenStreetMap","licence":"ODbL","url":"https://www.openstreetmap.org/node/4962498454"}],"recupere":"2026-11-14","site":"https://www.quatrehomme.fr/","adresse":"9 Rue du Général Leclerc, 92130 Issy-les-Moulineaux","tel":"+33 1 55 92 00 12","horaires":"Tu-Sa 09:00-19:45; Su 09:00-13:00"},{"id":"dt-c3a23ea7-f070-31da-82d3-5006c119ffdc","cat":"hotels","ville":"issy-les-moulineaux","nom":"Domaine de la Reine Margot","lat":48.822826,"lon":2.277161,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/c3a23ea7-f070-31da-82d3-5006c119ffdc"}],"recupere":"2026-11-14","long":{"fr":"Le Domaine de la Reine Margot, hôtel MGallery de Jean-Michel Wilmotte à Issy-les-Moulineaux, allie luxe et tranquillité dans un cadre bucolique avec vue panoramique sur Paris Ouest. Chambres offrant vue sur la tour Eiffel, jardin à la française, parc parfumé, terrasses ombragées, spa, piscine, et deux bars dont une chapelle reconvertie en bar à rhum vous promettent une escapade exclusive mémorable."},"site":"http://domainereinemargot.com/","adresse":"3 cours de la Reine Margot, 92130 Issy-les-Moulineaux","labels":["Tourisme & Handicap auditif","Tourisme & Handicap visuel","Clef Verte","5 étoiles"],"majSource":"2026-09-01"},{"id":"dt-8a41d463-7b82-3a53-898b-592b2d70db48","cat":"hotels","ville":"issy-les-moulineaux","nom":"Okko Hotels Paris Porte de Versailles","lat":48.832756,"lon":2.278226,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/8a41d463-7b82-3a53-898b-592b2d70db48"}],"recupere":"2026-11-14","long":{"fr":"Découvrez le confort et l'élégance de l'OKKO HOTELS Paris Porte de Versailles, un établissement 4 étoiles avec des chambres de 18m2. Profitez de draps en lin et coton, literie exclusive Coco-Mat et produits cosmétiques naturels Omnisens. Restez connectés grâce au Wi-Fi, salon ouvert toute la journée avec horaires flexibles d'arrivée et de départ. Idéalement situé près du parc des expositions et des stations de métro Balard et Porte de Versailles pour un accès facile au cœur de Paris. Profitez du salon, salle de repassage et espace forme ouverts de 7h à 22h pour un séjour inoubliable !"},"site":"https://www.okkohotels.com/fr/page/paris-porte-de-versailles/okko-hotels-paris-porte-de-versailles-hotel-paris-expo.3097.html","adresse":"2 rue du Colonel Pierre Avia, 75015 Paris","labels":["4 étoiles"],"majSource":"2026-09-01"},{"id":"dt-7b970b7a-cfb1-3fa1-b392-cf10712a7fb1","cat":"hotels","ville":"issy-les-moulineaux","nom":"Novotel Paris Centre Tour Eiffel","lat":48.849873,"lon":2.283264,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/7b970b7a-cfb1-3fa1-b392-cf10712a7fb1"}],"recupere":"2026-11-14","long":{"fr":"Vivez un séjour inoubliable au cœur de Paris au Novotel Paris Centre Tour Eiffel. Idéal pour un week-end en amoureux, des vacances en famille ou un déplacement professionnel, cet hôtel propose des chambres confortables. Proche des monuments, musées, boutiques et quartiers typiques de la capitale, tout est à portée de main. Profitez du restaurant Benkay pour déguster une cuisine japonaise, du fitness ou de la piscine (supplément). Vivez l'art de vivre parisien au Novotel."},"site":"https://www.novotel-paris-toureiffel.com/fr/","adresse":"61 quai de Grenelle, 75015 Paris","labels":["4 étoiles","Clef Verte"],"majSource":"2026-09-01"},{"id":"dt-1aff46fa-accd-3e4a-b719-e61aedca3097","cat":"hotels","ville":"issy-les-moulineaux","nom":"Hôtel Beaugrenelle Saint-Charles Tour Eiffel","lat":48.847233,"lon":2.285935,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/1aff46fa-accd-3e4a-b719-e61aedca3097"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé près de la Tour Eiffel et de la Porte de Versailles, l'hôtel Beaugrenelle Saint Charles Tour Eiffel propose 50 chambres confortables. Dès 13 heures, plongez dans une atmosphère chaleureuse. Profitez du wifi gratuit et d'un petit-déjeuner buffet disponible à partir de 7 heures. Un parking sécurisé se trouve à 50 mètres. Découvrez le quartier animé de Beaugrenelle avec ses commerces et brasseries. Une immersion authentique au cœur de Paris vous attend."},"site":"http://www.beaugrenelleparis.com/","adresse":"82 rue Saint-Charles, 75015 Paris","labels":["3 étoiles"],"majSource":"2026-09-01"},{"id":"dt-5f4ad304-a136-3984-ad86-36b60b7d6a63","cat":"hotels","ville":"issy-les-moulineaux","nom":"Hôtel Alize Grenelle Tour Eiffel","lat":48.84678,"lon":2.287771,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/5f4ad304-a136-3984-ad86-36b60b7d6a63"}],"recupere":"2026-11-14","long":{"fr":"Proche de la Tour Eiffel, du Centre Commercial Beaugrenelle, de la Porte de Versailles, et des Hôpitaux Necker et Georges Pompidou, séjournez à l'hôtel Alizé Grenelle Tour Eiffel. Profitez de 50 chambres modernes, wifi gratuit, petit-déjeuner buffet à 7h, déjeuner en chambre dès 8h, et parking sécurisé à 50m. Imprégnez-vous de la vie parisienne avec boulangeries, brasseries, restaurants et cinéma à proximité. Réservez maintenant pour une expérience authentique!"},"site":"http://www.alizeparis.com/","adresse":"87 avenue Émile Zola, 75015 Paris","labels":["3 étoiles"],"majSource":"2026-09-01"},{"id":"dt-a1e44ae7-9a0e-34a8-bb49-63bff9e23dc5","cat":"hotels","ville":"issy-les-moulineaux","nom":"Le Platine Hôtel","lat":48.847385,"lon":2.283331,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/a1e44ae7-9a0e-34a8-bb49-63bff9e23dc5"}],"recupere":"2026-11-14","long":{"fr":"Idéalement situé à quelques pas de la Tour Eiffel, du centre commercial Beaugrenelle et des rives de la Seine, le Platine Hôtel bénéficie d'un emplacement privilégié au cœur de la vie trépidante de Paris. Avec ses 46 chambres au style chic et iconique, inspirées de l'âge d'or hollywoodien des années 50, cet hôtel saura séduire les amateurs de glamour et d'élégance. Une adresse de choix pour un séjour empreint de charme et de raffinement dans la capitale."},"site":"http://www.platinehotel.fr/","adresse":"20 rue de l’ingénieur Robert Keller, 75015 Paris","labels":["4 étoiles"],"majSource":"2026-09-01"},{"id":"dt-7f293dee-e229-350a-8ecf-363b9e54eb8b","cat":"musees","ville":"issy-les-moulineaux","nom":"Musée français de la carte à jouer et galerie d'histoire de la ville","lat":48.822655,"lon":2.273522,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/7f293dee-e229-350a-8ecf-363b9e54eb8b"}],"recupere":"2026-11-14","long":{"fr":"Le Musée Français de la Carte à Jouer d'Issy-les-Moulineaux plonge dans l'histoire des jeux de cartes à travers les âges. Sa scénographie ingénieuse offre un voyage du XVe au XXe siècle, explorant différentes cultures, techniques de fabrication et créations artistiques. Installé dans un bâtiment contemporain relié à un pavillon historique, ce musée ravira les amateurs de cartes et d'histoire par son expérience immersive unique en France."},"site":"https://www.museecarteajouer.com/","adresse":"16 rue Auguste Gervais, 92130 Issy-les-Moulineaux","majSource":"2026-09-01"},{"id":"dt-b6b01d78-f8b2-3ac3-a902-933c02770682","cat":"parcs","ville":"issy-les-moulineaux","nom":"Parc Suzanne Lenglen","lat":48.83038,"lon":2.271416,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/b6b01d78-f8b2-3ac3-a902-933c02770682"}],"recupere":"2026-11-14","long":{"fr":"Le parc omnisports Suzanne Lenglen, lieu de détente et de sport, propose de nombreuses activités au sein d'un environnement végétal varié. Les rhododendrons, azalées, cerisiers du Japon et érables bordent un chemin vallonné. Les enfants ont accès à des aires de jeux. La ferme urbaine pédagogique, au 82 rue Henri Farman, héberge des animaux comme des chèvres naines, moutons d'Ouessant, poules, dindons, oies, canards et lapins pour le plaisir des familles en quête de nature."},"site":"https://www.paris.fr/","adresse":"2 rue Louis Armand, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-f1acac12-1b11-3e53-bd06-9df1f1c96674","cat":"loisirs","ville":"issy-les-moulineaux","nom":"Centre sportif Suzanne Lenglen","lat":48.830284,"lon":2.274085,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/f1acac12-1b11-3e53-bd06-9df1f1c96674"}],"recupere":"2026-11-14","long":{"fr":"Le complexe sportif offre une large gamme d'activités pour les amateurs de sport. Avec un boulodrome, un terrain de football ou de rugby, un parcours de jogging, 14 courts de tennis, un espace dédié au football américain, et une piste d'athlétisme de 400 mètres, les sportifs de tous niveaux trouveront leur bonheur. Que ce soit pour une partie conviviale entre amis ou un entraînement intensif, chacun pourra s'épanouir dans cette structure complète et moderne."},"site":"https://www.paris.fr/","adresse":"2 rue Louis Armand, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-73d84d70-fc20-3b8c-82d7-cdf3b0f59a4a","cat":"loisirs","ville":"issy-les-moulineaux","nom":"Aquaboulevard de Paris","lat":48.831802,"lon":2.276263,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/73d84d70-fc20-3b8c-82d7-cdf3b0f59a4a"}],"recupere":"2026-11-14","long":{"fr":"Plongez dans une expérience incroyable à l’Aquaboulevard de Paris, le plus grand parc aquatique urbain d’Europe ! Avec ses 2 bassins à vagues, 11 toboggans, jacuzzis, rivières et plage de sable fin, vous profiterez d’un moment de bonheur en famille. L’hygiène et la sécurité sont essentielles : l’eau est traitée en continu, les maîtres-nageurs veillent sur vous, des caméras et un personnel discret surveillent. Amusez-vous en toute tranquillité à l’Aquaboulevard !"},"site":"https://www.aquaboulevard.fr/","adresse":"4-6 rue Louis Armand, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-c81e0973-faa7-3920-97cf-ec49bae6441c","cat":"patrimoine","ville":"issy-les-moulineaux","nom":"Tour aux Figures - Jean Dubuffet","lat":48.828495,"lon":2.258532,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/c81e0973-faa7-3920-97cf-ec49bae6441c"}],"recupere":"2026-11-14","long":{"fr":"En 1988, Jean Dubuffet dévoile la Tour aux Figures au parc de l'Île Saint-Germain à Issy-les-Moulineaux. Cette œuvre monumentale en béton et acier, haute de 24 mètres, représente le mouvement de l'Hourloupe (1962-1974) de l'artiste. Classée monument historique en 2008, la tour domine une colline du parc. Les visiteurs peuvent même explorer l'intérieur lors de visites guidées, plongeant ainsi dans l'univers artistique unique de Dubuffet."},"site":"https://tourauxfigures.hauts-de-seine.fr/","adresse":"Parc départemental de l'Île Saint-Germain, 92130 Issy-les-Moulineaux","majSource":"2026-09-01"},{"id":"dt-9370e2f7-ed7b-3eb7-8cf6-62f50cd08eb4","cat":"patrimoine","ville":"issy-les-moulineaux","nom":"Centre d’Art Contemporain Chanot (CACC)","lat":48.81249,"lon":2.266102,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/9370e2f7-ed7b-3eb7-8cf6-62f50cd08eb4"}],"recupere":"2026-11-14","long":{"fr":"Le Centre d’Art Contemporain Chanot, à Clamart, à 7 minutes de la gare Montparnasse, est un ancien atelier d’artiste devenu espace d’exposition depuis 1980. Il présente peintures, dessins, sculptures, photographies, vidéos, performances, graphismes et architecture. Des activités gratuites telles que visites guidées, rencontres artistes, lectures, conférences et masterclass sont organisées pour favoriser les échanges artistiques."},"site":"https://www.clamart.fr/fr/centre-dart-contemporain-chanot","adresse":"33 rue Brissard, 92140 Clamart","majSource":"2026-09-01"},{"id":"dt-1552e148-da37-322c-bcba-44f3036476b5","cat":"musees","ville":"issy-les-moulineaux","nom":"Les Étincelles du Palais de la Découverte","lat":48.840954,"lon":2.27965,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/1552e148-da37-322c-bcba-44f3036476b5"}],"recupere":"2026-11-14","long":{"fr":"Les Étincelles, créées par l'atelier Construire et Charpente Cénomane, offrent un espace temporaire d'activités pendant la rénovation du Palais de la Découverte. Évoquant l'éclat des démonstrations scientifiques renommées du Palais, cette structure en bois respectueuse de l'environnement se situe près du Jardin Caroline Aigle, au cœur du Parc André-Citroën. Un mélange harmonieux entre modernité et tradition pour continuer à émerveiller les passionnés de science et de découvertes."},"site":"https://www.palais-decouverte.fr/fr/venir-nous-voir/les-etincelles","adresse":"Jardin Caroline Aigle - 186 rue Saint Charles, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-9f8a18e6-6136-3bd0-98d2-9da33e0cd357","cat":"loisirs","ville":"issy-les-moulineaux","nom":"Pathé Aquaboulevard","lat":48.83281,"lon":2.276933,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/9f8a18e6-6136-3bd0-98d2-9da33e0cd357"}],"recupere":"2026-11-14","long":{"fr":"Le cinéma Gaumont Aquaboulevard possède 14 salles, dont une équipée de projection numérique. Toutes en gradin et climatisées, ces salles offrent une qualité sonore optimale. Avec des fauteuils club rouges spacieux, des larges accoudoirs et porte-gobelets, ainsi qu'un espacement d'1,10m entre les allées, les spectateurs bénéficient d'un confort ultime lors de leur séance."},"site":"http://www.cinemasgaumontpathe.com/","adresse":"8 rue du Colonel Pierre Avia, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-7d647486-38d6-378f-899f-8927639a88c8","cat":"loisirs","ville":"issy-les-moulineaux","nom":"Bowling Front de Seine","lat":48.84915,"lon":2.284399,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/7d647486-38d6-378f-899f-8927639a88c8"}],"recupere":"2026-11-14","long":{"fr":"Profitez d'une expérience de bowling exceptionnelle dans notre établissement doté de 20 pistes de qualité. Que vous soyez débutant ou joueur confirmé, vous trouverez le plaisir de défier vos amis ou votre famille dans une ambiance conviviale et dynamique. Venez perfectionner vos techniques, partager des moments de complicité et vivre des parties endiablées jusqu'au bout de la nuit. Avec nos installations modernes et notre équipe chaleureuse, le bowling n'aura jamais été aussi divertissant !"},"site":"http://www.xbowlingsympas.com/","adresse":"11 rue Gaston de Caillavet, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-b8561bb8-fb15-3af3-85e2-f0f0eeaf79b6","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Quai liberté - Table de Wu et guinguette","lat":48.848381,"lon":2.279387,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/b8561bb8-fb15-3af3-85e2-f0f0eeaf79b6"}],"recupere":"2026-11-14","long":{"fr":"Le restaurant à bord offre 80 places assises avec une vue imprenable sur la statue de la liberté et une cuisine bistronomique signée du Chef Alfredo Martin. Situé le long des quais de Seine, la guinguette, ouverte de Mai à Octobre, s'étend sur 1000m2. Elle propose une ambiance festive et conviviale où vous pourrez déguster street food, bières et cocktails à des prix attractifs. Profitez d'une expérience culinaire et festive unique en plein cœur de Paris !"},"site":"https://quailiberte.fr/","adresse":"6 port haut javel, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-38dbb416-c56b-3ff4-bc2d-941c178dd389","cat":"musees","ville":"issy-les-moulineaux","nom":"Musée Français de la Carte à Jouer","lat":48.822678,"lon":2.27342,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Conseil Départemental des Yvelines","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/13/38dbb416-c56b-3ff4-bc2d-941c178dd389"}],"recupere":"2026-11-14","long":{"fr":"Le Musée français de la carte à jouer propose de découvrir l'univers fascinant des cartes à jouer, de toutes les époques et de tous les continents. Ses collections exceptionnelles vous dévoilent les origines des jeu, la fabrication, la cartomancie..."},"site":"https://www.museecarteajouer.com/","adresse":"16 rue Auguste Gervais, 92130 Issy-les-Moulineaux","majSource":"2026-02-02"},{"id":"dt-52b1149f-698b-3020-b9da-8972d73fadbd","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Benkay","lat":48.85003,"lon":2.283413,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/52b1149f-698b-3020-b9da-8972d73fadbd"}],"recupere":"2026-11-14","long":{"fr":"Le Benkay, prestigieux restaurant japonais du 15e arrondissement, jouit d'une vue imprenable sur la Seine. Casseroles en main, les chefs nippons experts en washoku, la cuisine traditionnelle, concoctent sous vos yeux ébahis des mets d'exception. Du succulent bœuf teriyaki aux sushis délicatement préparés, en passant par le teppanyaki sur plaque chauffante, la gastronomie japonaise s'invite dans votre assiette pour une expérience culinaire sans pareil."},"site":"http://www.restaurant-benkay.com/","adresse":"Novotel Paris Centre Tour Eiffel - 61 quai de Grenelle, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-1d773c60-676f-3622-8448-f747297cfcb2","cat":"shopping","ville":"issy-les-moulineaux","nom":"Beaugrenelle Paris","lat":48.848324,"lon":2.282361,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/1d773c60-676f-3622-8448-f747297cfcb2"}],"recupere":"2026-11-14","long":{"fr":"À proximité de la Tour Eiffel et en face de la statue de la Liberté, Beaugrenelle Paris est un centre commercial élégant et relaxant en bord de Seine. Avec plus de 100 marques allant de la mode à la maison, un multiplexe de 10 salles conçu par le célèbre designer Ora-ïto, et une diversité de restaurants offrant une vue imprenable sur le fleuve, cet endroit saura satisfaire toutes les envies de shopping et de détente."},"site":"https://www.beaugrenelle-paris.com/","adresse":"12 rue Linois, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-4f2c68da-1985-3adb-b586-41a6e42ac09e","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Panasia","lat":48.849247,"lon":2.282663,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/4f2c68da-1985-3adb-b586-41a6e42ac09e"}],"recupere":"2026-11-14","long":{"fr":"Situé au cœur de l'Îlot Panoramic du Centre Commercial Beaugrenelle, le restaurant Panasia propose un voyage culinaire unique près de la tour Eiffel. Fusionnant les saveurs emblématiques de l'Extrême-Orient, il offre une cuisine mêlant influences chinoises, japonaises, coréennes, vietnamiennes, thaïlandaises, cambodgiennes et indonésiennes. Une immersion dans les délices de l'Asie, dans un cadre exotique et raffiné."},"site":"http://www.panasia.fr/","adresse":"Centre Commercial Beaugrenelle - Ilôt Panoramic - 1er étage - 7 rue Linois, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-e77341da-ceb6-3d43-bb00-50f3596853d2","cat":"shopping","ville":"issy-les-moulineaux","nom":"Weill Stock","lat":48.845467,"lon":2.284348,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/e77341da-ceb6-3d43-bb00-50f3596853d2"}],"recupere":"2026-11-14","long":{"fr":"Découvrez les collections Weill et Atika à prix doux chez nous ! Une sélection variée de pièces chics et intemporelles pour toutes les occasions. Tailleur élégant, robe raffinée, manteau classique : tout pour un dressing élégant à prix abordables. Qualité et style au quotidien avec nos dernières créations. Renouvelez votre garde-robe avec des pièces de choix signées Weill et Atika !"},"site":"https://www.weill.com/fr/","adresse":"102 rue Saint-Charles, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-dce13e8b-18d3-394c-8533-7d60aaeb51d4","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Trattoria en Seine sur le Théo","lat":48.849632,"lon":2.280874,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/dce13e8b-18d3-394c-8533-7d60aaeb51d4"}],"recupere":"2026-11-14","long":{"fr":"Sur le port de Grenelle, en face de la Statue de la Liberté, la compagnie Diamant Bleu propose un diner-croisière ou un brunch-croisière à bord du Daniel's. Dans un décor moderne et raffiné, on navigue sur la Seine en savourant de délicieuses spécialités italiennes, en famille, entre amis ou en couple. Le bateau dispose d’une terrasse extérieure qui permet d’admirer les plus beaux monuments de Paris."},"site":"https://www.le-diamant-bleu.fr/","adresse":"Port de Beaugrenelle – Entrée par le pont de Grenelle, rive gauche (côté tour Eiffel), 75015 Paris","majSource":"2026-09-01"},{"id":"dt-5d436d60-bc6b-338c-ba14-d241ad56c154","cat":"patrimoine","ville":"issy-les-moulineaux","nom":"Monument aux morts pour la France en opérations extérieures","lat":48.83815,"lon":2.276913,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/5d436d60-bc6b-338c-ba14-d241ad56c154"}],"recupere":"2026-11-14","long":{"fr":"Situé dans le parc André-Citroën à Paris, le Monument aux Morts pour la France en opérations extérieures rend hommage aux militaires tombés depuis 1963. Inauguré en 2019, il se compose d’une sculpture monumentale et d’un mur portant les noms de plus de 600 soldats. Accès libre toute l’année."},"site":"https://for.onac-vg.fr/hauts-lieux-memoire-necropoles/monument-aux-morts-pour-la-france-en-operations-exterieures","adresse":"29 rue de la Montagne de la Fage - Jardin Eugénie Djendi - Parc André Citroën, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-b5c52e72-2768-366a-9d82-b302314fb62f","cat":"musees","ville":"issy-les-moulineaux","nom":"Maison de la culture du Japon à Paris","lat":48.854717,"lon":2.289646,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/b5c52e72-2768-366a-9d82-b302314fb62f"}],"recupere":"2026-11-14","long":{"fr":"Plongez au cœur de la culture japonaise à Paris à la Maison de la culture du Japon ! Depuis plus de 15 ans, découvrez les trésors nippons à travers 8 activités incontournables : expositions, spectacles, projections cinématographiques, conférences, bibliothèque, langue japonaise, gastronomie. Profitez d'une immersion totale avec des cours variés : cérémonie du thé, origami, calligraphie, art floral. Explorez la diversité de la culture japonaise !"},"site":"http://www.mcjp.fr/","adresse":"101 bis quai Branly, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-f22a6dff-a506-3da7-acb8-864fb722de91","cat":"restaurants","ville":"issy-les-moulineaux","nom":"radioeat","lat":48.853091,"lon":2.280436,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/f22a6dff-a506-3da7-acb8-864fb722de91"}],"recupere":"2026-11-14","long":{"fr":"Le restaurant Radioeat, conçu par l'architecte Stéphane Maupin, offre une vue imprenable sur la Seine et la tour Eiffel. Situé à la Maison de la Radio, il propose une cuisine de brasserie moderne par le chef Thierry Bassard. Fraîcheur, simplicité et santé caractérisent sa carte. Profitez d'une expérience gustative et culturelle unique!"},"site":"https://www.maisondelaradioetdelamusique.fr/","adresse":"Maison de la Radio et de la Musique - 116 avenue du Président Kennedy - 1er étage - Galerie Seine, 75016 Paris","majSource":"2026-09-01"},{"id":"dt-ef427406-4250-3e3a-afd4-650dec5f2910","cat":"nature","ville":"issy-les-moulineaux","nom":"Cirque Bormann","lat":48.837635,"lon":2.270817,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/ef427406-4250-3e3a-afd4-650dec5f2910"}],"recupere":"2026-11-14","long":{"fr":"Le Cirque Bormann, en héritage depuis 7 générations, enchante avec ses numéros époustouflants : jonglage, chevaux, trapèze, et clowneries. Installé dans le 15e à Paris, ce lieu exceptionnel, en partenariat avec la mairie, propose une expérience unique : hall d'accueil de 250m², chapiteau 1000 places et espace annexe de 150m². Plongez dans ce monde magique et fascinant, sous le chapiteau baroque des Bormann. Une escapade cirque inoubliable à vivre absolument !"},"adresse":"5 rue Lucien Bossoutrot, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-31d3deb0-148e-3090-804f-b883370ae470","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Les Quatre Saisons","lat":48.84656,"lon":2.279794,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/31d3deb0-148e-3090-804f-b883370ae470"}],"recupere":"2026-11-14","long":{"fr":"Venez explorer les délices de la cuisine coréenne au restaurant Les Quatre Saisons ! Plongez dans un univers culinaire riche en saveurs et en authenticité. Laissez-vous séduire par des mets traditionnels revisités avec talent. Une expérience gustative inoubliable vous attend dans ce lieu où les saveurs de la Corée s'invitent à votre table. Une escapade gastronomique à ne pas manquer pour les amateurs de nouvelles sensations culinaires !"},"adresse":"17 avenue Emile Zola, 75015 Paris","majSource":"2026-09-01"},{"id":"dt-16e86106-83e0-3235-9955-ab4f8e2de1fb","cat":"restaurants","ville":"issy-les-moulineaux","nom":"Capitaine Fracasse","lat":48.855183,"lon":2.286958,"prix":{"type":"inconnu"},"photo":null,"sources":[{"nom":"DATAtourisme · Paris je t'aime - Office de Tourisme","licence":"Licence Ouverte 2.0","url":"https://data.datatourisme.fr/19/16e86106-83e0-3235-9955-ab4f8e2de1fb"}],"recupere":"2026-11-14","long":{"fr":"Embarquez à bord du Capitaine Fracasse pour une croisière de 2 heures sur la Seine à partir de 54€! Départ de l'Ile aux cygnes, passage par le Pont Bir-Hakeim près de la Tour Eiffel jusqu'à la Bibliothèque François Mitterrand. Profitez d'un dîner à partir de 67€ avec des plats traditionnels : tartare de crabe aux agrumes, suprême de pintade fermière Label Rouge, entremet tout chocolat. Menu enfant disponible ! Une expérience culinaire à ne pas manquer!"},"adresse":"Embarquement sur l'île aux cygnes - Accessible par le milieu du Pont Bir-Hakeim, 75015 Paris","majSource":"2026-09-01"}]);
